    statusGet: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Default Response */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "generated_at": "2026-11-08T12:02:03.701Z",
                     *       "services": [
                     *         {
                     *           "family": "company",
                     *           "status": "operational",
                     *           "uptime_7d": 0.956,
                     *           "uptime_30d": 0.985,
                     *           "uptime_90d": 0.985
                     *         }
                     *       ],
                     *       "universe": {
                     *         "companies": 6225,
                     *         "earnings_calls": {
                     *           "scope": "all",
                     *           "companies": 5535
                     *         }
                     *       }
                     *     }
                     */
                    "application/json": {
                        /** Format: date-time */
                        generated_at: string;
                        /** @description Status and uptime per product family; null while unavailable */
                        services: Array<{
                            /**
                             * @description Product family
                             * @enum {string}
                             */
                            family: "company" | "earnings_calls" | "financials" | "insider_trades" | "institutional_ownership" | "ipos" | "market" | "metadata" | "news" | "sec_filings";
                            /**
                             * @description Over the last 24 hours; too little traffic to judge reads as operational
                             * @enum {string}
                             */
                            status: "degraded" | "operational" | "outage";
                            /** @description Share of requests answered without a server error over the last 7 days (3 decimals); null with too little traffic to judge */
                            uptime_7d: null | number;
                            /** @description Share of requests answered without a server error over the last 30 days (3 decimals); null with too little traffic to judge */
                            uptime_30d: null | number;
                            /** @description Share of requests answered without a server error over the last 90 days (3 decimals); null with too little traffic to judge */
                            uptime_90d: null | number;
                        }> | null;
                        /** @description Status, uptime and 7-day p50 / p95 latency per docs group of the v2 API (v1 routes count in the group of the v2 operation that replaces them); null while unavailable */
                        groups?: Array<{
                            /**
                             * @description Docs group of the v2 API
                             * @enum {string}
                             */
                            group: "call_analytics" | "catalog" | "companies" | "documents" | "events" | "filings" | "financials" | "guidance" | "holdings" | "insider_trades" | "investor_documents" | "ipos" | "metrics" | "news" | "reference" | "transcripts" | "webhooks";
                            /** @description Docs group title (e.g. Insider trades) */
                            name: string;
                            /**
                             * @description Over the last 24 hours; too little traffic to judge reads as operational
                             * @enum {string}
                             */
                            status: "degraded" | "operational" | "outage";
                            /** @description Share of requests answered without a server error over the last 7 days (3 decimals); null with too little traffic to judge */
                            uptime_7d: null | number;
                            /** @description Share of requests answered without a server error over the last 30 days (3 decimals); null with too little traffic to judge */
                            uptime_30d: null | number;
                            /** @description Share of requests answered without a server error over the last 90 days (3 decimals); null with too little traffic to judge */
                            uptime_90d: null | number;
                            /** @description p50 latency over the last 7 days in ms, as the upper bound of its latency bucket (25, 50, 100, 200, 400, 800, 1600, 3200, 6400 or 12800); null with too little traffic to judge or above 12800 */
                            p50_ms_7d: null | number;
                            /** @description p95 latency over the last 7 days in ms, as the upper bound of its latency bucket (25, 50, 100, 200, 400, 800, 1600, 3200, 6400 or 12800); null with too little traffic to judge or above 12800 */
                            p95_ms_7d: null | number;
                        }> | null;
                        /** @description Coverage universe */
                        universe: {
                            /** @description Listed (not delisted) companies; null while the data DB is unavailable */
                            companies: null | number;
                            earnings_calls: {
                                /** @description Earnings-call coverage scope (e.g. top500); unknown without data */
                                scope: string;
                                /** @description Companies in the earnings-call scope */
                                companies: number;
                            };
                        };
                    };
                };
            };
            500: components["responses"]["InternalServerError"];
            503: components["responses"]["ServiceUnavailableError"];
        };
    };
